&lt;li&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:100}&quot;&gt;&lt;span class=&quot;EOP Selected SCXW147630149 BCX8&quot; data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:320,&amp;quot;335559739&amp;quot;:120}&quot;&gt;&lt;span class=&quot;TextRun SCXW85258676 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW85258676 BCX8&quot;&gt;Experience with ML optimisation: RL, SFT, evolutionary methods, or similar. Experience optimising hard against a defined metric and making (and justifying) careful measurement choices.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW85258676 BCX8&quot; data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:100}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:100}&quot;&gt;&lt;span class=&quot;EOP Selected SCXW147630149 BCX8&quot; data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:320,&amp;quot;335559739&amp;quot;:120}&quot;&gt;&lt;span class=&quot;TextRun SCXW73800928 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW73800928 BCX8&quot;&gt;Strong written communication and argumentation: high-quality research write-ups in any medium — a paper, a blog post, an internal report, an unusually good thread — where the reasoning, not just the result, is the point.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW73800928 BCX8&quot; data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:100}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
